?php if($rows):?><ul><?php arsort($rows);foreach($rows as$name=>$count):?><li><?=e($name)?>: <strong><?=e($count)?></strong></li><?php endforeach;?></ul><?php else:?><span class="text-success small">Không có</span><?php endif;?></div><?php endforeach;?></div></aside></div><?php endif;?></div>
<div class="modal fade editor-modal" id="entryModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><div><h5 class="modal-title" id="entryTitle">Chỉnh tiết</h5><small class="text-muted" id="entryMeta"></small></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="alert alert-warning constraint-warning d-none" id="entryWarning"></div><form method="post" action="/tkb_xep.php" id="moveForm" class="row g-2"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="move"><input type="hidden" name="return_tab" value="plan"><input type="hidden" name="plan_id" value="<?=e($plan['id']??'')?>"><input type="hidden" name="return_tab" value="plan"><input type="hidden" name="return_mode" value="<?=e($mode)?>"><input type="hidden" name="return_class" value="<?=e($class)?>"><input type="hidden" name="return_teacher" value="<?=e($teacher)?>"><input type="hidden" name="activity_id" id="entryId"><div class="col-4"><label class="form-label">Thứ</label><select class="form-select" name="day" id="entryDay"><?php foreach($data['settings']['days']as$d):?><option value="<?=$d?>"><?=$d===8?'Chủ nhật':'Thứ '.$d?></option><?php endforeach;?></select></div><div class="col-4"><label class="form-label">Buổi</label><select class="form-select" name="session" id="entrySession"><option>Sáng</option><option>Chiều</option></select></div><div class="col-4"><label class="form-label">Tiết</label><input class="form-control" type="number" min="1" max="8" name="period" id="entryPeriod"></div><div class="col-12 text-end"><button class="btn btn-primary">Chuyển và khóa tiết</button></div></form><div class="d-flex justify-content-between mt-2"><form method="post" action="/tkb_xep.php" id="deleteEntryForm" onsubmit="return confirm('Xóa tiết này khỏi bảng và chuyển về Tiết chưa sắp?')"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="entry_delete"><input type="hidden" name="plan_id" value="<?=e($plan['id']??'')?>"><input type="hidden" name="return_tab" value="plan"><input type="hidden" name="return_mode" value="<?=e($mode)?>"><input type="hidden" name="return_class" value="<?=e($class)?>"><input type="hidden" name="return_teacher" value="<?=e($teacher)?>"><input type="hidden" name="activity_id" id="deleteEntryId"><button class="btn btn-outline-danger"><i class="bi bi-trash"></i> Xóa tiết</button></form><form method="post" action="/tkb_xep.php" id="lockForm" class="mt-2 text-end"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="lock"><input type="hidden" name="plan_id" value="<?=e($plan['id']??'')?>"><input type="hidden" name="return_tab" value="plan"><input type="hidden" name="return_mode" value="<?=e($mode)?>"><input type="hidden" name="return_class" value="<?=e($class)?>"><input type="hidden" name="return_teacher" value="<?=e($teacher)?>"><input type="hidden" name="activity_id" id="lockEntryId"><button class="btn btn-outline-warning" id="lockButton">Khóa tiết</button></form></div></div></div></div></div>
<div class="modal fade" id="renameModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form class="modal-content" method="post" action="/tkb_xep.php"><div class="modal-header"><h5 class="modal-title">Đặt tên phương án</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="rename_plan"><input type="hidden" name="return_tab" value="plan"><input type="hidden" name="plan_id" value="<?=e($plan['id']??'')?>"><input type="hidden" name="return_tab" value="plan"><input type="hidden" name="return_mode" value="<?=e($mode)?>"><input type="hidden" name="return_class" value="<?=e($class)?>"><input type="hidden" name="return_teacher" value="<?=e($teacher)?>"><label class="form-label">Tên phương án</label><input class="form-control" name="name" maxlength="120" required value="<?=e($plan['name']??'')?>"></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Hủy</button><button class="btn btn-primary">Lưu tên</button></div></form></div></div>
<div class="optimizer-overlay" id="optimizerOverlay"><div class="optimizer-panel"><div class="optimizer-percent" id="optimizerPercent">0%</div><div class="progress my-3"><div class="progress-bar progress-bar-striped progress-bar-animated" id="optimizerBar" style="width:0%"></div></div><div id="optimizerStatus">Đang đọc khối lượng của phiên bản tuần…</div><small class="text-muted d-block mt-2">Phương án mới vẫn được lưu trong phiên bản tuần hiện tại.</small></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>
document.querySelectorAll('.optimizer-form').forEach(function(form){form.addEventListener('submit',function(){var overlay=document.getElementById('optimizerOverlay'),bar=document.getElementById('optimizerBar'),number=document.getElementById('optimizerPercent'),status=document.getElementById('optimizerStatus'),p=0;overlay.classList.add('show');setInterval(function(){if(p<72)p+=Math.max(1,Math.round((72-p)/6));else if(p<94)p++;p=Math.min(94,p);bar.style.width=p+'%';number.textContent=p+'%';status.textContent=p<30?'Đang đọc khối lượng và ràng buộc tuần…':(p<65?'Đang lấp kín các tiết buổi sáng…':(p<88?'Đang xếp các tiết còn lại và tối ưu…':'Đang lưu phương án vào phiên bản tuần…'));},180)})});
document.querySelectorAll('[data-step]').forEach(function(button){button.addEventListener('click',function(){var select=this.parentElement.querySelector('.entity-select'),next=select.selectedIndex+Number(this.dataset.step);if(next<0)next=select.options.length-1;if(next>=select.options.length)next=0;select.selectedIndex=next;select.form.submit();});});
document.querySelectorAll('[data-side]').forEach(function(button){button.addEventListener('click',function(){document.querySelectorAll('[data-side]').forEach(function(b){b.classList.remove('active')});this.classList.add('active');document.getElementById('sideUnplaced').classList.toggle('d-none',this.dataset.side!=='unplaced');document.getElementById('sideDiagnostics').classList.toggle('d-none',this.dataset.side!=='diagnostics');});});
var violations=document.getElementById('showViolations');if(violations)violations.addEventListener('change',function(){document.body.classList.toggle('show-violations',this.checked);});
var days=<?=json_encode(array_values($data['settings']['days']))?>,allEntries=<?=json_encode(array_values($entries),JSON_UNESCAPED_UNICODE)?>,blocked=<?=json_encode(array_values((array)($data['blocked']??[])),JSON_UNESCAPED_UNICODE)?>,classBlocked=<?=json_encode(array_values((array)($data['class_blocked']??[])),JSON_UNESCAPED_UNICODE)?>,scopeBlocks=<?=json_encode(array_values((array)($data['scope_blocks']??[])),JSON_UNESCAPED_UNICODE)?>,limitSettings=<?=json_encode(['daily'=>(int)($data['settings']['max_subject_class_daily']??2),'session'=>(int)($data['settings']['max_subject_class_session']??1)])?>,limitExceptions=<?=json_encode((array)($data['subject_limit_exceptions']??[]),JSON_UNESCAPED_UNICODE)?>,selected=null,slotIndex=new Map(),teacherBlocked=new Set(),classBlockedSet=new Set(),schoolBlocked=new Set(),gradeBlocked=new Set(),scopeClassBlocked=new Set();
function slotKey(s){return String(s.day)+'|'+s.session+'|'+String(s.period)}
allEntries.forEach(function(e){var key=slotKey(e);if(!slotIndex.has(key))slotIndex.set(key,[]);slotIndex.get(key).push(e)});
blocked.forEach(function(b){teacherBlocked.add(b.teacher+'|'+slotKey(b))});classBlocked.forEach(function(b){classBlockedSet.add(b.class+'|'+slotKey(b))});scopeBlocks.forEach(function(b){var key=slotKey(b);if(b.scope==='school')schoolBlocked.add(key);else if(b.scope==='grade')gradeBlocked.add(String(b.value)+'|'+key);else if(b.scope==='class')scopeClassBlocked.add(String(b.value)+'|'+key)});
function overlaps(a,b){return a.teacher===b.teacher||(a.classes||[]).some(function(c){return(b.classes||[]).includes(c)})}
function isBlocked(e,s){var key=slotKey(s);if(schoolBlocked.has(key)||teacherBlocked.has(e.teacher+'|'+key))return true;return(e.classes||[]).some(function(c){var grade=(String(c).match(/^\d+/)||[''])[0];return classBlockedSet.has(c+'|'+key)||scopeClassBlocked.has(c+'|'+key)||(grade&&gradeBlocked.has(grade+'|'+key))})}
function limitsFor(subject){var x=limitExceptions[subject]||{},daily=Math.max(1,Number(x.daily||limitSettings.daily||2)),session=Math.max(1,Number(x.session||limitSettings.session||1));return{daily:daily,session:Math.min(daily,session)}}
function constraintReason(e,s,ignore){if(isBlocked(e,s))return'Giáo viên/lớp bận hoặc ô không học';if(e.fixed_day&&(Number(s.day)!==Number(e.fixed_day)||s.session!==e.fixed_session||Number(s.period)!==Number(e.fixed_period)))return'Tiết đã được xếp cố định';if(e.pair_id){var partner=allEntries.find(function(x){return x.pair_id===e.pair_id&&x.activity_id!==e.activity_id});if(partner&&(Number(s.day)!==Number(partner.day)||s.session!==partner.session||Math.abs(Number(s.period)-Number(partner.period))!==1))return'Phải giữ liền với tiết còn lại trong cặp'}var ignored=new Set(ignore||[]),limits=limitsFor(e.subject);for(var i=0;i<(e.classes||[]).length;i++){var c=e.classes[i],daily=0,session=0;allEntries.forEach(function(x){if(ignored.has(x.activity_id)||x.subject!==e.subject||!(x.classes||[]).includes(c)||Number(x.day)!==Number(s.day))return;daily++;if(x.session===s.session)session++});if(daily>=limits.daily)return'Đã đủ '+limits.daily+' tiết môn/lớp/ngày';if(session>=limits.session)return'Đã đủ '+limits.session+' tiết môn/lớp/buổi'}return''}
function cellSlot(cell){var row=cell.parentElement;return{day:days[cell.cellIndex-1],session:row.dataset.session,period:Number(row.querySelector('th span').textContent)}}
function conflicts(e,s,ignore){var ignored=new Set(ignore);return(slotIndex.get(slotKey(s))||[]).filter(function(x){return!ignored.has(x.activity_id)&&overlaps(e,x)})}
function clearTargets(){document.querySelectorAll('.schedule-grid td').forEach(function(c){c.classList.remove('move-ok','swap-ok','move-no');delete c.dataset.action;delete c.dataset.targetId;delete c.title});document.querySelectorAll('.lesson.selected').forEach(function(x){x.classList.remove('selected')})}
function markTargets(e,button){clearTargets();selected=e;button.classList.add('selected');document.querySelectorAll('.schedule-grid td').forEach(function(cell){var target=cellSlot(cell),hits=conflicts(e,target,[e.activity_id]);var reason=constraintReason(e,target,[e.activity_id].concat(hits.map(function(x){return x.activity_id})));if(reason){cell.classList.add('move-no');cell.title=reason;return}if(hits.length===0){cell.classList.add('move-ok');cell.dataset.action='move';return}if(hits.length===1){var other=hits[0],source={day:e.day,session:e.session,period:Number(e.period)},otherBlocked=constraintReason(other,source,[e.activity_id,other.activity_id]),otherHits=conflicts(other,source,[e.activity_id,other.activity_id]),moveHits=conflicts(e,target,[e.activity_id,other.activity_id]);if(!otherBlocked&&!otherHits.length&&!moveHits.length&&!constraintReason(e,target,[e.activity_id,other.activity_id])){cell.classList.add('swap-ok');cell.dataset.action='swap';cell.dataset.targetId=other.activity_id;return}}cell.classList.add('move-no')})}
function postMove(cell){if(!selected||!cell.dataset.action)return;var slot=cellSlot(cell),form=document.createElement('form');form.method='post';form.action='/tkb_xep.php';var fields={csrf:'<?=e($csrf)?>',action:cell.dataset.action,return_tab:'plan',plan_id:'<?=e($plan['id']??'')?>',activity_id:selected.activity_id,day:slot.day,session:slot.session,period:slot.period,target_id:cell.dataset.targetId||'',return_mode:'<?=e($mode)?>',return_class:'<?=e($class)?>',return_teacher:'<?=e($teacher)?>'};Object.keys(fields).forEach(function(name){var input=document.createElement('input');input.type='hidden';input.name=name;input.value=fields[name];form.appendChild(input)});document.body.appendChild(form);form.submit()}
function openEditor(e){document.getElementById('entryTitle').textContent=e.subject+' · '+(e.classes||[]).join(' + ');document.getElementById('entryMeta').textContent=e.teacher;var warning=document.getElementById('entryWarning');warning.textContent=e.warning||'';warning.classList.toggle('d-none',!e.warning);document.getElementById('entryId').value=e.activity_id;document.getElementById('lockEntryId').value=e.activity_id;document.getElementById('deleteEntryId').value=e.activity_id;document.getElementById('entryDay').value=e.day;document.getElementById('entrySession').value=e.session;document.getElementById('entryPeriod').value=e.period;document.querySelectorAll('#moveForm select,#moveForm input[type="number"],#moveForm button').forEach(function(control){control.disabled=!!e.fixed_day});document.getElementById('lockButton').textContent=e.locked?'Mở khóa tiết':'Khóa tiết';bootstrap.Modal.getOrCreateInstance(document.getElementById('entryModal')).show()}
document.querySelectorAll('.lesson').forEach(function(lesson){var e=JSON.parse(lesson.dataset.entry),full=Object.assign({},allEntries.find(function(x){return x.activity_id===e.id})||{},e);lesson.draggable=!e.locked&&!e.fixed_day;lesson.addEventListener('click',function(){if(e.locked||e.fixed_day)openEditor(full);else markTargets(full,this)});lesson.addEventListener('dblclick',function(){openEditor(full)});lesson.addEventListener('dragstart',function(ev){if(e.locked||e.fixed_day){ev.preventDefault();openEditor(full);return}markTargets(full,this);this.classList.add('dragging');ev.dataTransfer.effectAllowed='move'});lesson.addEventListener('dragend',function(){this.classList.remove('dragging')})});
document.querySelectorAll('.schedule-grid td').forEach(function(cell){cell.addEventListener('dragover',function(ev){if(selected&&this.dataset.action)ev.preventDefault()});cell.addEventListener('drop',function(ev){ev.preventDefault();postMove(this)});cell.addEventListener('click',function(ev){if(selected&&this.dataset.action&&!ev.target.closest('.lesson'))postMove(this)})});
</script></body></html>
